  if(amt!=null&&isFinite(+amt)){var s=el("span","sep","·");s.setAttribute("aria-hidden","true");x.appendChild(s);x.appendChild(el("span","amt",usd(amt)))}else x.appendChild(el("span","nc","no cost recorded"))}
function paintReceipt(a){var id="FR-"+a.id,b=$("r-rcp");
  fetch("../receipts/"+encodeURIComponent(id)+".json").then(function(r){if(!r.ok)throw 0;return r.json()}).then(function(j){
    var p=j.price||{};rcpFill(b,j.receipt_id||id,p.recorded&&p.usd!=null?p.usd:null);b.hidden=false}).catch(function(){b.hidden=true})}
function chip(cls,text,icon){var c=el("span","chip c-"+cls);c.appendChild(ic(icon||cls));c.appendChild(document.createTextNode(text));return c}
